CREATE TABLE refunds_changes (
    change_id  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    op         text NOT NULL,
    refund_id  bigint NOT NULL,
    row_data   jsonb,
    changed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE FUNCTION log_refund_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO refunds_changes (op, refund_id) VALUES (TG_OP, OLD.refund_id);
        RETURN OLD;
    END IF;
    INSERT INTO refunds_changes (op, refund_id, row_data) VALUES (TG_OP, NEW.refund_id, to_jsonb(NEW));
    RETURN NEW;
END $$;

CREATE TRIGGER refunds_capture AFTER INSERT OR UPDATE OR DELETE ON refunds
    FOR EACH ROW EXECUTE FUNCTION log_refund_change();

