data class Change(val lsn: String, val xid: String, val data: String)

fun peek(conn: java.sql.Connection, max: Int = 1_000): List<Change> =
    conn.prepareStatement(
        "SELECT lsn::text, xid::text, data FROM pg_logical_slot_peek_changes('refunds_cdc', NULL, ?)"
    ).use { ps ->
        ps.setInt(1, max)
        ps.executeQuery().use { rs ->
            buildList { while (rs.next()) add(Change(rs.getString(1), rs.getString(2), rs.getString(3))) }
        }
    }

