fun rowEvents(before: Map<Long, Row>, after: Map<Long, Row>): List<RowEvent> =
    (before.keys + after.keys).sorted().mapNotNull { id ->
        val old = before[id]
        val new = after[id]
        when {
            old == null && new != null -> RowEvent.Inserted(new)
            old != null && new == null -> RowEvent.Deleted(id)
            old != null && new != null && old != new -> RowEvent.Updated(new)
            else -> null
        }
    }

// Twice is harmless: each event says what the row IS (or that it is gone), never what to add to it.
